/* Gamestage fonts, arcade theme. Arcade sets everything in DM Sans, the base
   face, so this declares the same face as gamestage-fonts.css and ships no
   file of its own. Its character comes from colour, depth and weight, not a
   second face: one face per theme, GSUI-292, Tom 2026-09-28. */

@font-face {
  font-family: 'DM Sans';
  font-style: normal;
  font-weight: 400 900;
  font-display: swap;
  src: url('./gamestage-fonts/dm-sans-latin.woff2') format('woff2');
  unicode-range: U+0000-00FF, U+0131, U+0152-0153, U+02BB-02BC, U+02C6, U+02DA,
    U+02DC, U+0304, U+0308, U+0329, U+2000-206F, U+20AC, U+2122, U+2191, U+2193,
    U+2212, U+2215, U+FEFF, U+FFFD;
}
